<?php
declare(strict_types=1);use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;defined('_JEXEC')or die;
$s=htmlspecialchars((string)$params->get('moduleclass_sfx',''),ENT_QUOTES,'UTF-8');
?><div class="mod-joomleague-birthdays<?php echo$s;?>"><?php if(isset($birthdays['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($birthdays['error']);?></div><?php elseif($birthdays['items']===[]):?><div class="alert alert-info mb-0"><?php echo Text::_('MOD_JOOMLEAGUE_BIRTHDAYS_EMPTY');?></div><?php else:?><div class="list-group list-group-flush"><?php foreach($birthdays['items']as$p):$name=trim((string)$p->first_name.' '.(string)$p->last_name);?><a class="list-group-item list-group-item-action px-0 d-flex align-items-center gap-3" href="<?php echo Route::_('index.php?option=com_joomleague&view=person&person_id='.(int)$p->id);?>"><?php if((int)$params->get('show_images',1)===1&&$p->picture):?><img src="<?php echo htmlspecialchars((string)$p->picture,ENT_QUOTES,'UTF-8');?>" alt="" width="48" height="48" class="img-fluid" loading="lazy"><?php else:?><span class="icon-user fs-4 text-body-secondary" aria-hidden="true"></span><?php endif;?><span class="flex-grow-1"><strong class="d-block"><?php echo htmlspecialchars($name,ENT_QUOTES,'UTF-8');?></strong><?php if((int)$params->get('show_club',1)===1&&$p->club_name):?><small class="text-body-secondary"><?php echo htmlspecialchars((string)$p->club_name,ENT_QUOTES,'UTF-8');?></small><?php endif;?></span><span class="text-end"><time datetime="<?php echo$p->next_birthday->format('Y-m-d');?>"><?php echo htmlspecialchars($p->next_birthday->format(Text::_('MOD_JOOMLEAGUE_BIRTHDAYS_DATE_FORMAT')),ENT_QUOTES,'UTF-8');?></time><?php if((int)$params->get('show_age',0)===1):?><small class="d-block text-body-secondary"><?php echo Text::sprintf('MOD_JOOMLEAGUE_BIRTHDAYS_AGE',(int)$p->age);?></small><?php endif;?></span></a><?php endforeach;?></div><?php endif;?></div>
